struct point2 {
    double x;
    double y;
};

int main(void) {
    struct point2 p = { 0.1, 0.2 };     // x = 0.1, y = 0.2
    struct point2 origin = { 0 };       // every member 0.0
    struct point2 q = { .y = 5.0, .x = -1.0 };   // by name, any order

    printf("p = (%f, %f)\n", p.x, p.y);
    printf("origin = (%f, %f)\n", origin.x, origin.y);
    printf("q = (%f, %f)\n", q.x, q.y);

    p.x = 100.0;            // change one member
    p.y = p.y * 10;
    printf("p = (%f, %f)\n", p.x, p.y);
    printf("sizeof(struct point2) = %zu\n", sizeof(struct point2));
    return 0;
}

