#include <stdio.h>

struct point2 {
    double x;
    double y;
};

int main(void) {
    struct point2 p = { 1.0, 2.0 };
    struct point2 *ptr = &p;      // ptr points at p

    // explicit dereference: brackets needed because . binds tighter than *
    (*ptr).x = 100.0;
    (*ptr).y = 200.0;
    printf("p = (%f, %f)\n", (*ptr).x, (*ptr).y);

    // arrow: dereference and pick a member in one step
    ptr->x = -1.5;
    ptr->y = -2.5;
    printf("p = (%f, %f)\n", ptr->x, ptr->y);
    printf("p.x = %f\n", p.x);    // p itself changed
    return 0;
}

#include <stdio.h>

struct student {
    char name[32];
    int id;
    double gpa;
};

// Prints the student that s points at. const: print only reads.
void print_student(const struct student *s) {
    printf("%s (%d): GPA %.1f\n", s->name, s->id, s->gpa);
}

// Raises the GPA of the student that s points at (at most 4.3).
void raise_gpa(struct student *s, double amount) {
    s->gpa += amount;
    if (s->gpa > 4.3) {
        s->gpa = 4.3;
    }
}

int main(void) {
    struct student a = { "Ada", 20231, 3.6 };
    struct student b = { "Linus", 20232, 4.1 };

    print_student(&a);
    print_student(&b);

    raise_gpa(&a, 0.3);
    raise_gpa(&b, 0.3);
    print_student(&a);
    print_student(&b);
    return 0;
}

