    char title[32];
    char author[32];
    int year;
};

void print_book(const struct book *b) {
    printf("%s by %s (%d)\n", b->title, b->author, b->year);
}

// Returns a pointer to the oldest book in books (n >= 1).
struct book *oldest(struct book books[], size_t n) {
    size_t best = 0;
    for (size_t i = 1; i < n; i++) {
        if (books[i].year < books[best].year) {
            best = i;
        }
    }
    return &books[best];
}

int main(void) {
    struct book shelf[3] = {
        { "Dune", "Herbert", 1965 },
        { "Emma", "Austen", 1815 },
        { "Neuromancer", "Gibson", 1984 }
    };
    size_t n = 3;

    for (size_t i = 0; i < n; i++) {
        print_book(&shelf[i]);
    }
    printf("oldest: ");
    print_book(oldest(shelf, n));
    printf("shelf[2].title[0] = %c\n", shelf[2].title[0]);
    printf("sizeof(shelf) = %zu\n", sizeof(shelf));
    return 0;
}

#include <stdio.h>
#include <string.h>

struct wordinfo {
    char first;
    size_t len;
};

// Fills info[0..n-1] from words[0..n-1].
// info is really a pointer to the caller's array, so the caller sees the changes.
void fill(struct wordinfo info[], char *words[], size_t n) {
    for (size_t i = 0; i < n; i++) {
        info[i].first = words[i][0];
        info[i].len = strlen(words[i]);
    }
}

int main(void) {
    char *words[] = { "struct", "pointer", "arrow" };
    struct wordinfo info[3];        // members not set yet

    fill(info, words, 3);
    for (size_t i = 0; i < 3; i++) {
        printf("%c %zu\n", info[i].first, info[i].len);
    }
    return 0;
}

