#include <stdio.h>

struct time {
    int hours;      // 0 to 23
    int minutes;    // 0 to 59
};

// Prints the time that t points at as HH:MM.
void print_time(const struct time *t) {
    printf("%02d:%02d\n", t->hours, t->minutes);
}

// Adds m minutes (m >= 0) to the time that t points at, wrapping past midnight.
void add_minutes(struct time *t, int m) {
    int total = t->hours * 60 + t->minutes + m;
    t->hours = (total / 60) % 24;
    t->minutes = total % 60;
}

int main(void) {
    struct time start = { 9, 45 };
    struct time late = { 23, 30 };

    add_minutes(&start, 50);
    add_minutes(&late, 45);
    print_time(&start);
    print_time(&late);
    return 0;
}

// Output:
// 10:35
// 00:15

