#include <stdio.h>

struct letters {
    char first;
    int vowels;
};

// For each i from 0 to n - 1, stores the first character of words[i]
// and the number of lower-case vowels in words[i] in out[i].
void analyse(char *words[], struct letters out[], size_t n) {
    for (size_t i = 0; i < n; i++) {
        out[i].first = words[i][0];
        out[i].vowels = 0;
        for (size_t j = 0; words[i][j] != '\0'; j++) {
            char c = words[i][j];
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                out[i].vowels++;
            }
        }
    }
}

int main(void) {
    char *words[] = { "queue", "stack", "tree" };
    struct letters out[3];

    analyse(words, out, 3);
    for (size_t i = 0; i < 3; i++) {
        printf("%s: starts with %c, %d vowels\n", words[i], out[i].first, out[i].vowels);
    }
    return 0;
}

write.prompt:
Write a complete C program that:

1. defines a struct type `struct book` with three members: a title and an author (strings of at most 63 characters) and the year it was published (an integer);
2. defines a function `print_book` that takes a **pointer** to a `struct book` and prints its three members, one per line, as `Title: ...`, `Author: ...`, `Year: ...`;
3. in `main`, declares and initialises two books (for example Dune, Frank Herbert, 1965 and Emma, Jane Austen, 1815) and prints both using `print_book`.

write.solution:
#include <stdio.h>

struct book {
    char title[64];
    char author[64];
    int year;
};

// Prints the book that b points at.
void print_book(struct book *b) {
    printf("Title: %s\n", b->title);
    printf("Author: %s\n", b->author);
    printf("Year: %d\n", b->year);
}

int main(void) {
    struct book b1 = { "Dune", "Frank Herbert", 1965 };
    struct book b2 = { "Emma", "Jane Austen", 1815 };

    print_book(&b1);
    print_book(&b2);
    return 0;
}

// Output:
// Title: Dune
// Author: Frank Herbert
// Year: 1965
// Title: Emma
// Author: Jane Austen
// Year: 1815
